def encoded(v):
    return (json.dumps(v, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode()

def digest(data):
    return hashlib.sha256(data).hexdigest()

def sha(v):
    return type(v) is str and len(v) == 64 and all((c in '0123456789abcdef' for c in v))

def finite(v):
    return type(v) in (int, float) and math.isfinite(v)

def positive(v):
    return type(v) is int and v > 0

def parsed(data):

    def pairs(rows):
        d = {}
        for k, v in rows:
            if k in d:
                raise ValueError('Duplicate launch metadata key.')
            d[k] = v
        return d

    def bad(v):
        raise ValueError('Nonfinite launch metadata: ' + v)
    return json.loads(data, object_pairs_hook=pairs, parse_constant=bad)

def safe(name):
    if type(name) is not str:
        raise ValueError('Canonical private source path required.')
    p = PurePosixPath(name)
    if not name or len(name) > 768 or p.is_absolute() or ('..' in p.parts) or ('.' in p.parts) or (p.as_posix() != name) or ('\\' in name):
        raise ValueError('Canonical private source path required.')
    return p.parts

def dir_id(s):
    return (s.st_dev, s.st_ino, s.st_uid, stat.S_IMODE(s.st_mode))

def file_id(s):
    return (*dir_id(s), s.st_nlink, s.st_size, s.st_mtime_ns)

def private_read(root, binding, name, cap):
    """Read one exact anchored private file; never follow a source symlink."""
    root = Path(root)
    parts = safe(name)
    if not root.is_absolute() or root.resolve(strict=True) != root or str(root) != binding['root'] or (str(root.parent) != binding['parent']) or (list(dir_id(root.lstat())) != binding['root_identity']) or (list(dir_id(root.parent.lstat())) != binding['parent_identity']) or (binding['root_identity'][2:] != [os.getuid(), 448]) or (type(cap) is not int) or (not 0 <= cap <= 2 * 2 ** 20):
        raise ValueError('Bound private source root/cap required.')
    fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    parents = []
    try:
        if list(dir_id(os.fstat(fd))) != binding['root_identity']:
            raise ValueError('Held source root changed.')
        for part in parts[:-1]:
            before = os.stat(part, dir_fd=fd, follow_symlinks=False)
            if not stat.S_ISDIR(before.st_mode) or before.st_dev != binding['root_identity'][0] or before.st_uid != os.getuid() or (stat.S_IMODE(before.st_mode) != 448):
                raise ValueError('Private source ancestor required.')
            child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            if dir_id(os.fstat(child)) != dir_id(before):
                os.close(child)
                raise ValueError('Source ancestor changed.')
            parents.append((fd, part, before))
            fd = child
        before = os.stat(parts[-1], dir_fd=fd, follow_symlinks=False)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or before.st_uid != os.getuid() or (before.st_dev != binding['root_identity'][0]) or (stat.S_IMODE(before.st_mode) != 384) or (not 0 <= before.st_size <= cap):
            raise ValueError('Private bounded single-link source file required.')
        filefd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW, dir_fd=fd)
        try:
            if file_id(os.fstat(filefd)) != file_id(before):
                raise ValueError('Source changed before read.')
            chunks = []
            size = 0
            while size <= cap:
                data = os.read(filefd, min(2 ** 20, cap + 1 - size))
                if not data:
                    break
                chunks.append(data)
                size += len(data)
            if file_id(os.fstat(filefd)) != file_id(before):
                raise ValueError('Source changed during read.')
        finally:
            os.close(filefd)
        if size != before.st_size or file_id(os.stat(parts[-1], dir_fd=fd, follow_symlinks=False)) != file_id(before):
            raise ValueError('Named source changed during read.')
        for parent, part, want in parents:
            if dir_id(os.stat(part, dir_fd=parent, follow_symlinks=False)) != dir_id(want):
                raise ValueError('Source ancestry changed during read.')
        if root.resolve(strict=True) != root or list(dir_id(root.lstat())) != binding['root_identity']:
            raise ValueError('Source root changed after read.')
        return b''.join(chunks)
    finally:
        os.close(fd)
        for parent, _, _ in reversed(parents):
            os.close(parent)

def control(data):
    if type(data) is not bytes or len(data) > 256 * 1024:
        raise ValueError('Bounded component control required.')
    c = parsed(data)
    if type(c) is not dict or set(c) != {'kind', 'policy_text', 'policy_sha256', 'supervisor_sources'} or c['kind'] != 'pgd-candidate-supervised-control-v1' or (encoded(c) != data):
        raise ValueError('Exact canonical component control required.')
    p = parsed(c['policy_text'])
    validate_policy(p, c['supervisor_sources'])
    if digest(c['policy_text'].encode()) != c['policy_sha256']:
        raise ValueError('Component policy digest changed.')
    return (c, p, digest(data))

def authorization(data, control_sha256):
    if type(data) is not bytes or len(data) > 64 * 1024:
        raise ValueError('One bounded scoped authorization required.')
    a = parsed(data)
    if type(a) is not dict or set(a) != {'kind', 'approved', 'control_sha256', 'maximum_new_attempts', 'user_basis'} or a['kind'] != 'pgd-candidate-supervised-university-exception-v1' or (a['approved'] is not True) or (a['control_sha256'] != control_sha256) or (type(a['maximum_new_attempts']) is not int) or (a['maximum_new_attempts'] != 1) or (type(a['user_basis']) is not str) or (not 1 <= len(a['user_basis']) <= 8192):
        raise ValueError('One new exact supervised split grant required; no old scope reuse.')
    return a

def installation(c, sha256):
    data = encoded({'kind': 'pgd-split-scratch-installation-v1', 'control_sha256': sha256, 'files': c['supervisor_sources']})
    return (data, digest(data))

class PinnedImporter(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Only fixed project names from held, verified bytes; no cwd/package fallback."""

    def __init__(self, root, binding, c, policy):
        self.kind = 'pgd-split-pinned-importer-v1'
        self.root = Path(root)
        self.binding = binding
        self.control_sha256 = digest(encoded(c))
        self.files = {}
        self.loaded = set()
        self.installed = False
        mapping = {}
        for path, d in parsed(policy['scratch_contract_text'])['runtime_files'].items():
            if not path.endswith('.py'):
                raise ValueError('Only declared Python runtime source.')
            name = path[:-3].replace('/', '.')
            if name.endswith('.__init__'):
                name = name[:-len('.__init__')]
            if name in mapping:
                raise ValueError('Duplicate installed project module name.')
            mapping[name] = ('overlay/' + path, d)
        for name, path in SUPERVISORS.items():
            if name in mapping:
                raise ValueError('Supervisor/runtime namespace collision.')
            mapping[name] = ('supervisor/' + path, c['supervisor_sources'][path])
        if len(mapping) != 45:
            raise ValueError('Exact39candidate runtime and six supervisor names required.')
        for name, (path, d) in mapping.items():
            data = private_read(root, binding, path, d['bytes'])
            if len(data) != d['bytes'] or digest(data) != d['sha256']:
                raise ValueError('Source hash/extent changed before import: ' + path)
            self.files[name] = (path, data, path.endswith('/__init__.py'))

    def find_spec(self, fullname, path=None, target=None):
        if fullname.split('.')[0] in ('models', 'attacks'):
            if target is not None:
                raise ImportError('Pinned project reload refused.')
            if '.' in fullname:
                parent = fullname.rsplit('.', 1)[0]
                module = sys.modules.get(parent)
                if module is None or getattr(module, '__loader__', None) is not self or path != getattr(module, '__path__', None):
                    raise ImportError('Exact already-loaded private project parent/search path required.')
            elif path is not None:
                raise ImportError('Top-level pinned package cannot use an ambient path.')
        if fullname.split('.')[0] not in ('models', 'attacks'):
            return None
        if fullname not in self.files:
            raise ModuleNotFoundError('Unpinned project import refused: ' + fullname)
        if fullname in self.loaded:
            raise ImportError('Project module reload refused: ' + fullname)
        relative, data, package = self.files[fullname]
        return importlib.util.spec_from_loader(fullname, self, origin=str(self.root / relative), is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__name__
        if name not in self.files or name in self.loaded:
            raise ImportError('One pinned module execution only.')
        self.loaded.add(name)
        relative, data, package = self.files[name]
        module.__file__ = str(self.root / relative)
        module.__cached__ = None
        if package:
            module.__path__ = [str((self.root / relative).parent)]
        if private_read(self.root, self.binding, relative, len(data)) != data:
            raise ImportError('Source changed around pinned module execution.')
        exec(compile(data, module.__file__, 'exec'), module.__dict__)
        if private_read(self.root, self.binding, relative, len(data)) != data:
            raise ImportError('Source changed around pinned module execution.')

    def install(self):
        if self.installed or any((n.split('.')[0] in ('models', 'attacks') for n in sys.modules)):
            raise ValueError('Fresh project module namespace required; no reuse.')
        self.installed = True
        sys.meta_path.insert(0, self)
        return self

def validate_plan(plan, csha, session, now):
    keys = {'kind', 'control_sha256', 'authorization_sha256', 'role', 'nonce', 'parent_pid', 'root_binding', 'launch_started', 'deadline', 'work_deadline', 'connection_deadline', 'session_sha256', 'source_hashes'}
    if type(plan) is not dict or set(plan) != keys or plan['kind'] != 'pgd-candidate-child-launch-v1' or (plan['control_sha256'] != csha) or (plan['role'] not in ROLES) or (not all((sha(plan[k]) for k in ('control_sha256', 'authorization_sha256', 'nonce', 'session_sha256')))) or (not positive(plan['parent_pid'])) or (not all((finite(plan[k]) for k in ('launch_started', 'deadline', 'work_deadline', 'connection_deadline')))) or (not finite(now)) or (not plan['launch_started'] <= now < plan['deadline'] <= min(plan['launch_started'] + SECONDS[plan['role']], plan['work_deadline'])) or (plan['work_deadline'] > plan['connection_deadline']):
        raise ValueError('Original role/launch-origin/deadline binding required.')
    expected = STATIC['source_hashes'] if plan['role'] == 'forward-preserving' else {}
    if type(plan['source_hashes']) is not dict or plan['source_hashes'] != expected:
        raise ValueError('Exact immutable candidate source/reference hashes required.')
    if session.get('kind') != 'pgd-candidate-parent-session-v1' or session.get('control_sha256') != csha or session.get('parent_pid') != plan['parent_pid'] or (session.get('current') != {k: plan[k] for k in ('role', 'nonce', 'launch_started', 'deadline', 'source_hashes')}) or (session.get('work_deadline') != plan['work_deadline']) or (session.get('connection_deadline') != plan['connection_deadline']) or (session.get('completed') != list(ROLES[:ROLES.index(plan['role'])])) or (session.get('phase') != 'running') or (session.get('complete') is not False) or (not finite(session.get('connection_started'))) or (session['work_deadline'] != session['connection_started'] + 2400) or (session['connection_deadline'] != session['connection_started'] + 3000):
        raise ValueError('Exact fresh serial parent/session role required.')
    return plan

def wait_release(fd, parent_pid, deadline):
    """Future child waits before bootstrap/model imports; tests use fake fd APIs."""
    if not positive(fd) or not positive(parent_pid) or os.getppid() != parent_pid or (not finite(deadline)):
        raise ValueError('Owned inherited release descriptor required.')
    if not stat.S_ISFIFO(os.fstat(fd).st_mode):
        raise ValueError('Anonymous release pipe required.')
    remaining = deadline - time.monotonic()
    if not 0 < remaining <= 1680:
        raise TimeoutError('Original child deadline exhausted before release.')
    signal.signal(signal.SIGALRM, signal.SIG_DFL)
    signal.setitimer(signal.ITIMER_REAL, remaining)
    try:
        ready, _, _ = select.select([fd], [], [], remaining)
        if ready != [fd] or os.read(fd, 2) != b'G' or os.getppid() != parent_pid or (time.monotonic() >= deadline):
            raise ValueError('Parent did not release this exact still-owned child.')
    finally:
        os.close(fd)

def child_entry(plan_bytes):
    """Uninvoked concrete child entry; future reviewed driver performs release first."""
    global _CHILD_USED
    if _CHILD_USED:
        raise ValueError('One child entry; no retries.')
    _CHILD_USED = True
    if type(plan_bytes) is not bytes or len(plan_bytes) > 16 * 1024:
        raise ValueError('Bounded child launch metadata required.')
    plan = parsed(plan_bytes)
    root = Path(plan['root_binding']['root'])
    binding = plan['root_binding']
    cbytes = private_read(root, binding, 'control.json', 256 * 1024)
    c, p, csha = control(cbytes)
    abytes = private_read(root, binding, 'authorization.json', 64 * 1024)
    authorization(abytes, csha)
    if digest(abytes) != plan['authorization_sha256']:
        raise ValueError('Authorization bytes changed.')
    sbytes = private_read(root, binding, 'session.json', 128 * 1024)
    if digest(sbytes) != plan['session_sha256']:
        raise ValueError('Parent session changed before dispatch.')
    validate_plan(plan, csha, parsed(sbytes), time.monotonic())
    if os.getppid() != plan['parent_pid'] or os.getsid(0) != os.getpid() or os.getpgrp() != os.getpid():
        raise ValueError('Fresh still-owned child session required.')
    PinnedImporter(root, binding, c, p).install()
    from models import predictor_pgd_split_coordinator_v1 as coordinator
    if os.getppid() != plan['parent_pid'] or time.monotonic() >= plan['deadline']:
        raise TimeoutError('Original owner/phase changed during source installation.')
    return coordinator.dispatch_child(root, binding, cbytes, abytes, plan)

def require_namespace(root, binding, csha):
    candidates = [v for v in sys.meta_path if getattr(v, 'kind', None) == 'pgd-split-pinned-importer-v1' and getattr(v, 'root', None) == Path(root) and (getattr(v, 'binding', None) == binding) and (getattr(v, 'control_sha256', None) == csha) and getattr(v, 'installed', False)]
    if len(candidates) != 1:
        raise ValueError('One trusted fresh pinned component importer required.')
    finder = candidates[0]
    for name, module in list(sys.modules.items()):
        if name.split('.')[0] not in ('models', 'attacks'):
            continue
        if name not in finder.files or name not in finder.loaded:
            raise ValueError('Unpinned/preloaded project namespace refused.')
        path, data, package = finder.files[name]
        expected = str(Path(root) / path)
        if getattr(module, '__file__', None) != expected or getattr(module, '__loader__', None) is not finder or getattr(getattr(module, '__spec__', None), 'loader', None) is not finder or (getattr(module.__spec__, 'origin', None) != expected) or (package and getattr(module, '__path__', None) != [str((Path(root) / path).parent)]):
            raise ValueError('Pinned project origin/loader/path changed.')
        if private_read(root, binding, path, len(data)) != data:
            raise ValueError('Loaded source bytes changed.')
        if '.' in name:
            parent, child = name.rsplit('.', 1)
            if getattr(sys.modules.get(parent), child, None) is not module:
                raise ValueError('Pinned project parent-child identity changed.')
    return finder
